func port(cmd *cobra.Command, args []string) error {
    if len(args) != 1 {
        return fmt.Errorf("need exactly one port")
    }
    if _, err := strconv.Atoi(args[0]); err != nil {
        return fmt.Errorf("%q is not a port", args[0])
    }
    return nil
}

rootCmd := &cobra.Command{
    Use:  "serve <port>",
    Args: port,
    Run: func(cmd *cobra.Command, args []string) {
        fmt.Println("Listening on :" + args[0])
    },
}

